#include <android/log.h>
#include <atomic>
#include <cstdio>

namespace recomp::audio { void diagnosticDumpXma(); void diagnosticDumpXmaContext(uint32_t address); }
// DIAGNOSTIC v72 (v53 probe ported and extended). sub_83140340's skip loop (loc_83140450) has no
// iteration bound: it repeats sub_836A9768 until the samples counted by sub_836A96D8 before the lock
// are consumed, and spins when sub_836A9768 keeps returning 0 (hostage-scene stall). Always on:
// per call a few thread-local stores at entry, a record at the stream-switch path (loc_83140688),
// a zero-return counter in the skip loop. Logs: RENDER_DIAG_XMA_SWITCH (first 8 switches, then
// powers of two), RENDER_DIAG_XMA_SWITCH_LEFTOVER (a switch with samples still owed in r23: the
// precondition of the spin; first 32, then powers of two) and, once the spin is certain (2^20 and
// 2^26 consecutive zero returns), RENDER_DIAG_XMA_SKIP_SPIN/_CALL/_SLOT/_VOICE/_LOCAL/_HW plus the
// pool's RENDER_DIAG_XMA_CTX and RENDER_DIAG_XMA_EVENT lines.
namespace {
struct RecompDiagXmaCall {
	uint32_t engine, entryIdx, entryVoice, entryAvail, switches;
	uint32_t swR23, swR30, swR21, swR22, swOld8, swOld12, swOld16, swOld20, sw2744, swVoice;
};
thread_local RecompDiagXmaCall recompDiagXmaCall{};
thread_local unsigned recompDiagXmaSkipZero = 0;
std::atomic<unsigned long long> recompDiagXmaSwitchCount{0}, recompDiagXmaLeftoverCount{0};
void recompDiagXmaEntry(PPCContext& __restrict ctx, uint8_t* base) {
	const uint32_t e = ctx.r28.u32, idx = PPC_LOAD_U32(e + 2712);
	recompDiagXmaCall = {};
	recompDiagXmaCall.engine = e; recompDiagXmaCall.entryIdx = idx;
	recompDiagXmaCall.entryVoice = PPC_LOAD_U32(e + 2632 + idx * 40); recompDiagXmaCall.entryAvail = ctx.r3.u32;
}
void recompDiagXmaSwitch(PPCContext& __restrict ctx, uint8_t* base) {
	const uint32_t e = ctx.r28.u32, slot = ctx.r31.u32;
	auto& c = recompDiagXmaCall;
	++c.switches; c.swR23 = ctx.r23.u32; c.swR30 = ctx.r30.u32; c.swR21 = ctx.r21.u32; c.swR22 = ctx.r22.u32 & 0xFF;
	c.swOld8 = PPC_LOAD_U32(slot + 8); c.swOld12 = PPC_LOAD_U32(slot + 12); c.swOld16 = PPC_LOAD_U32(slot + 16);
	c.swOld20 = PPC_LOAD_U32(slot + 20); c.sw2744 = PPC_LOAD_U32(e + 2744); c.swVoice = PPC_LOAD_U32(slot + 0);
	const auto n = ++recompDiagXmaSwitchCount;
	if (n <= 8 || !(n & (n - 1)))
		__android_log_print(ANDROID_LOG_INFO, "RecompRenderer",
			"RENDER_DIAG_XMA_SWITCH n=%llu engine=%08x idx=%u r23=%u r30=%u r22=%u old8=%u old12=%u old16=%u old20=%u queued=%u loop=%u",
			n, e, PPC_LOAD_U32(e + 2712), c.swR23, c.swR30, c.swR22, c.swOld8, c.swOld12, c.swOld16, c.swOld20, c.sw2744,
			PPC_LOAD_U32(slot + 32));
	if (ctx.r23.u32) {
		const auto m = ++recompDiagXmaLeftoverCount;
		if (m <= 32 || !(m & (m - 1))) {
			const uint32_t other = e + 2632 + (((PPC_LOAD_U32(e + 2712) + 1) & 1) * 40);
			__android_log_print(ANDROID_LOG_INFO, "RecompRenderer",
				"RENDER_DIAG_XMA_SWITCH_LEFTOVER n=%llu engine=%08x r23=%u old8=%u old16=%u old20=%u queued=%u next_voice=%08x next12=%u next20=%u",
				m, e, c.swR23, c.swOld8, c.swOld16, c.swOld20, c.sw2744, PPC_LOAD_U32(other + 0), PPC_LOAD_U32(other + 12),
				PPC_LOAD_U32(other + 20));
		}
	}
}
void recompDiagXmaVoice(uint8_t* base, const char* which, uint32_t voice) {
	if (!voice) { __android_log_print(ANDROID_LOG_INFO, "RecompRenderer", "RENDER_DIAG_XMA_SKIP_VOICE which=%s voice=0", which); return; }
	const uint32_t count = PPC_LOAD_U32(voice + 0), flags = PPC_LOAD_U32(voice + 4), entries = PPC_LOAD_U32(voice + 8);
	__android_log_print(ANDROID_LOG_INFO, "RecompRenderer", "RENDER_DIAG_XMA_SKIP_VOICE which=%s voice=%08x count=%u flags=%08x entries=%08x",
		which, voice, count, flags, entries);
	for (uint32_t i = 0; i < count && i < 4 && entries; ++i) {
		const uint32_t x = entries + i * 96;
		char line[24 * 9 + 1] = {};
		for (uint32_t k = 0; k < 24; ++k) snprintf(line + k * 9, 10, "%08x ", PPC_LOAD_U32(x + k * 4));
		__android_log_print(ANDROID_LOG_INFO, "RecompRenderer", "RENDER_DIAG_XMA_SKIP_LOCAL which=%s i=%u at=%08x w=%s", which, i, x, line);
		const uint32_t hw = PPC_LOAD_U32(x + 64);
		if (!hw) continue;
		for (uint32_t k = 0; k < 16; ++k) snprintf(line + k * 9, 10, "%08x ", PPC_LOAD_U32(hw + k * 4));
		line[16 * 9] = 0;
		__android_log_print(ANDROID_LOG_INFO, "RecompRenderer", "RENDER_DIAG_XMA_SKIP_HW which=%s i=%u at=%08x w=%s", which, i, hw, line);
		recomp::audio::diagnosticDumpXmaContext(hw);
	}
}
void recompDiagXmaSkipSpin(PPCContext& __restrict ctx, uint8_t* base) {
	const uint32_t e = ctx.r28.u32, slot = ctx.r31.u32, voice = PPC_LOAD_U32(slot + 0);
	__android_log_print(ANDROID_LOG_INFO, "RecompRenderer",
		"RENDER_DIAG_XMA_SKIP_SPIN zeros=%u engine=%08x slot=%08x voice=%08x r23=%u r29=%u r30=%u r22=%u r16=%u r21=%u "
		"cur=%u s2716=%u s2720=%u s2732=%u s2744=%u b2752=%u b2753=%u b2754=%u buf_cap=%u buf_fill=%u",
		recompDiagXmaSkipZero, e, slot, voice, ctx.r23.u32, ctx.r29.u32, ctx.r30.u32, ctx.r22.u32, ctx.r16.u32, ctx.r21.u32,
		PPC_LOAD_U32(e + 2712), PPC_LOAD_U32(e + 2716), PPC_LOAD_U32(e + 2720), PPC_LOAD_U32(e + 2732),
		PPC_LOAD_U32(e + 2744), PPC_LOAD_U8(e + 2752), PPC_LOAD_U8(e + 2753), PPC_LOAD_U8(e + 2754),
		PPC_LOAD_U32(e + 12), PPC_LOAD_U32(e + 24));
	const auto& c = recompDiagXmaCall;
	__android_log_print(ANDROID_LOG_INFO, "RecompRenderer",
		"RENDER_DIAG_XMA_SKIP_CALL same_engine=%u entry_idx=%u entry_voice=%08x entry_avail=%u switches=%u sw_r23=%u sw_r30=%u "
		"sw_r21=%u sw_r22=%u sw_old8=%u sw_old12=%u sw_old16=%u sw_old20=%u sw_queued=%u sw_voice=%08x total_switches=%llu leftovers=%llu",
		c.engine == e, c.entryIdx, c.entryVoice, c.entryAvail, c.switches, c.swR23, c.swR30, c.swR21, c.swR22, c.swOld8,
		c.swOld12, c.swOld16, c.swOld20, c.sw2744, c.swVoice, recompDiagXmaSwitchCount.load(), recompDiagXmaLeftoverCount.load());
	for (uint32_t k = 0; k < 2; ++k) {
		const uint32_t r = e + 2632 + k * 40;
		__android_log_print(ANDROID_LOG_INFO, "RecompRenderer",
			"RENDER_DIAG_XMA_SKIP_SLOT k=%u at=%08x w=%08x %08x %u %u %u %u %08x %08x %08x %08x", k, r,
			PPC_LOAD_U32(r + 0), PPC_LOAD_U32(r + 4), PPC_LOAD_U32(r + 8), PPC_LOAD_U32(r + 12), PPC_LOAD_U32(r + 16),
			PPC_LOAD_U32(r + 20), PPC_LOAD_U32(r + 24), PPC_LOAD_U32(r + 28), PPC_LOAD_U32(r + 32), PPC_LOAD_U32(r + 36));
	}
	recompDiagXmaVoice(base, "current", voice);
	const uint32_t other = PPC_LOAD_U32(e + 2632 + ((PPC_LOAD_U32(e + 2712) + 1) & 1) * 40);
	if (other != voice) recompDiagXmaVoice(base, "other", other);
	recomp::audio::diagnosticDumpXma();
}
}

// DIAGNOSTIC v72 (v53): count consecutive zero returns of the unbounded skip loop.
if (ctx.r3.u32 == 0) { const unsigned z = ++recompDiagXmaSkipZero; if (z == (1u << 20) || z == (1u << 26)) recompDiagXmaSkipSpin(ctx, base); }
else recompDiagXmaSkipZero = 0;
